"""Records-only scratch verifier; run with python3 -B from the checkout."""
import sys
sys.dont_write_bytecode = True
import collections, copy, difflib, hashlib, importlib.util, json, os, shutil, subprocess
from pathlib import Path
ROOT = Path.cwd()
TMP = Path('/tmp/fgos-work/w11-g9')
PLAN = Path('plans/260925-documentation-authority-unification')
COMP = PLAN / 'reports/phase-09/composition'
LEDGER = PLAN / 'ledger/decisions'
commands = []
sha = lambda b: hashlib.sha256(b.encode() if isinstance(b, str) else b).hexdigest()
def load(p): return json.loads(Path(p).read_text())
def save(p, value):
    p = Path(p); p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(json.dumps(value, ensure_ascii=False, indent=2) + '\n')
def run(argv, cwd=ROOT, input=None):
    r = subprocess.run(argv, cwd=cwd, input=input, capture_output=True)
    commands.append(dict(argv=list(map(str,argv)), cwd=str(cwd), exit=r.returncode,
                         stdout=r.stdout.decode(), stderr=r.stderr.decode()))
    save(TMP/'commands.json', commands)
    return r

def export(name='tree'):
    tree = TMP/name
    assert not tree.exists(), 'use a new scratch tree'
    tree.mkdir()
    r = run(['git','ls-files','-z']); assert r.returncode == 0
    paths = [Path(p.decode()) for p in r.stdout.split(b'\0') if p]
    allowed = {'docs','scripts','src','core','plugins','.agents','.claude','domains'}
    for p in paths:
        if p.parts[0] not in allowed or '.fgos' in p.parts or any(s in p.parts for s in ['node_modules','.env','secrets']): continue
        src = ROOT/p
        if src.is_symlink() or not src.is_file(): continue
        dst = tree/p; dst.parent.mkdir(parents=True,exist_ok=True); shutil.copyfile(src,dst)
    return tree

def replay(tree, packet, f=True, roundtrip=True):
    approved = load(ROOT/PLAN/'reports/phase-08/step-07-composed-patches.json')['patches']
    ext = {s['patchSpecId']:s for s in approved}
    byid = {s['id']:s for s in packet['patches']}
    ids = packet['effectiveSpecIds'] + (packet['finalPinFSpecIds'] if f else [])
    assert len(ids) == len(set(ids))
    steps=[]; originals={}; before_gloss={}; after_gloss={}
    def patch(s, reverse=False):
        path=s['path']; p=tree/path; p.parent.mkdir(parents=True, exist_ok=True)
        before = p.read_bytes() if p.exists() else b''
        assert sha(before) == s['expectedAfterSha256' if reverse else 'beforeSha256'],(s.get('id'), path, 'preimage')
        if not p.exists(): p.write_bytes(b'')
        diff=s['rollbackDiff' if reverse else 'diff']
        if diff:
            r=run(['patch','--batch','--fuzz=0','-p1'],tree,diff.encode()); assert r.returncode==0,(s.get('id'),r.stdout,r.stderr)
        after=p.read_bytes()
        assert sha(after)==s['beforeSha256' if reverse else 'expectedAfterSha256'], (s.get('id'),path,'postimage')
        return after
    for ident in ids:
        s=byid[ident]; path=s['path']; p=tree/path
        if path not in originals:
            original=(ROOT/path).read_bytes() if (ROOT/path).exists() else None
            originals[path]=original
            if not p.exists() and original is not None:
                p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(original)
            text=p.read_bytes() if p.exists() else b''
            if sha(text)!=s['beforeSha256']:
                pred=s.get('predecessor'); assert pred and pred['patchSpecId'] in ext,(ident,'external predecessor missing')
                e=ext[pred['patchSpecId']]; assert e['path']==path
                patch(e)
                if roundtrip: patch(e,True);patch(e)
                steps.append(e)
        if s.get('predecessor'):
            pred=s['predecessor']; parent=byid.get(pred['patchSpecId']) or ext[pred['patchSpecId']]
            assert s['beforeSha256']==pred['expectedAfterSha256']==parent['expectedAfterSha256'],ident
        if ident.startswith('w8:gloss:'): before_gloss[path]=p.read_text()
        patch(s)
        if roundtrip: patch(s,True);patch(s)
        steps.append(s)
        if ident.startswith('w8:gloss:'): after_gloss[path]=p.read_text()
    # Check full reverse rollback on a separate copy of just the changed files.
    ends={path:(tree/path).read_bytes() for path in originals}
    if roundtrip:
        for s in reversed(steps): patch(s,True)
        for path, original in originals.items():
            p=tree/path
            assert p.read_bytes()==(original if original is not None else b''),('full rollback',path)
            if original is None: p.unlink(); assert not p.exists()
        for path, content in ends.items(): (tree/path).write_bytes(content)
    return dict(effectiveSpecs=len(packet['effectiveSpecIds']),finalPinFSpecs=len(packet['finalPinFSpecIds']) if f else 0,
                predecessorApplications=len(steps)-len(ids),files=len(originals),steps=len(steps),
                fullRollbackExact=roundtrip, perStepRollbackExact=roundtrip,
                fileHashes=[dict(path=p,beforeSha256=sha(b or b''),initiallyAbsent=b is None,afterSha256=sha(ends[p])) for p,b in originals.items()]), before_gloss, after_gloss

def resolver(tree):
    spec=importlib.util.spec_from_file_location('bindings',ROOT/PLAN/'reports/phase-09/ledgerfix/bindings.py')
    b=importlib.util.module_from_spec(spec);spec.loader.exec_module(b)
    # Reuse both immutable extractors; relocate their scratch output only.
    adapter=ROOT/PLAN/'reports/phase-09/g0fix/extract-units.mjs'
    text=adapter.read_text(); old='/tmp/fgos-work/w3-ledger-fix-brief/extractors'
    assert text.count(old)==1
    dst=tree/PLAN/'reports/phase-09/g0fix/extract-units.mjs';dst.parent.mkdir(parents=True,exist_ok=True)
    dst.write_text(text.replace(old,str(TMP/'extractors')))
    for n in ['step10-round5-reproduction.json','step10-sync4d-reproduction.json','working-identity-registry.json']:
        p=PLAN/'reports/phase-06'/n;dst=tree/p;dst.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(ROOT/p,dst)
    return b

def catalog(b, tree, paths):
    # bindings.catalog invokes the existing Node adapter; record its command/exit too.
    before=len(commands)
    orig=subprocess.check_output
    def logged(argv, input=None, **kwargs):
        r=run(argv, tree, input); assert r.returncode==0,(argv,r.stderr)
        return r.stdout
    try:
        subprocess.check_output=logged
        data=b.catalog(paths)
    finally: subprocess.check_output=orig
    assert len(commands)==before+1
    return data['catalog']

if __name__=='__main__':
    packet=load(ROOT/COMP/'patch-specs.json')
    tree=export()
    proof, before, after=replay(tree,packet)
    save(TMP/'initial-replay.json',proof)
    save(TMP/'gloss-before.json',before);save(TMP/'gloss-after.json',after)
    b=resolver(tree)
    docs=b.documents();links=b.supersessions(docs)
    effective={}
    for file,doc in docs.items():
        for ptr,row in b.rows(doc):
            ef,ep,er=b.effective(file,ptr,row,docs,links)
            effective[(ef,ep)]=er
    paths={r['targetOwner'] for r in effective.values()}
    present=sorted(p for p in paths if (tree/p).is_file())
    cat=catalog(b,tree,present)
    save(TMP/'catalog-initial.json',cat)
    unresolved=[]
    for (file,ptr),row in effective.items():
        try: u=b.unit_for(row,cat)
        except (AssertionError,KeyError): unresolved.append(dict(shard=file,pointer=ptr,**b.payload(row)))
    save(TMP/'unresolved-initial.json',unresolved)
    print(json.dumps(dict(replay=proof,effectiveBindings=len(effective),targetFiles=len(paths),missingFiles=len(paths)-len(present),unresolved=len(unresolved),componentUnresolved=sum(r['targetOwner']=='docs/platform/component-boundary.md' for r in unresolved)),ensure_ascii=False))
